/* Pretend-player market (dates77). Runs on this device only. Later, real players replace these names. */
const YP_MARKET_KEY='yp.previewMarket.v1';
const YP_MARKET_OFFER_WEEKS=2;
const YP_MARKET_SETTLE_WEEKS=4;
const YP_MARKET_COUNTER_ROUNDS=4;
const YP_PRETEND_NAMES=['Riley Tanwell','Quinn Marbeck','Rowan Pell','Sage Ortley','Harper Dune','Jordan Merrin','Casey Wooln','Avery Sten','Morgan Cale','Taylor Venn','Peyton Ashmere','Cameron Brigg','Reese Linton','Drew Solway','Hayden Pruitt','Blair Kenning','Jamie Falbrook','Kendall Ost','Skyler Pimm','Elliot Wray'];

