function ypOpenBoarderView(id,boarderId){const L=ypBoardListing(id);const b=L&&(L.boarders||[]).find(x=>x.id===boarderId);const rec=ypOwnedRec(id);if(!L||!b)return;const price=ypGuideSale(id,rec);const facts=[];try{facts.push({label:'Type',amount:(typeof YP_FEED_TYPES!=='undefined'&&YP_FEED_TYPES[rec&&rec.tone])||'Building'});const beds=ypBedsOf(id,rec);const bedsText=typeof ypHomeBedsText==='function'?ypHomeBedsText(beds):'';if(bedsText)facts.push({label:'Bedrooms',amount:bedsText});}catch(e){}const flow=[{subhead:true,label:'Your Board'}];flow.push({label:'Weekly Board',value:ypMoneySafe(b.boardWk||L.boardWk)});flow.push({label:'What Is Included',value:L.included||'A room in this home'});if(Number.isFinite(+b.startWeek))flow.push({label:'Started',value:typeof ypGameWeekLabel==='function'?ypGameWeekLabel(b.startWeek):('Week '+b.startWeek)});const panelId='yp-boarder-view';if(typeof ypExclusive==='function')ypExclusive(panelId);const old=document.getElementById(panelId);if(old)old.remove();const panel=document.createElement('div');panel.id=panelId;panel.className='yp-market-steps';panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','yp-listing-title');const card=document.createElement('div');if(typeof ypMountListing==='function'){ypMountListing(card,{codeFor:id,money:[{label:'You Board Here',amount:ypMoneySafe(price),primary:true,value:price}].concat(facts),place:(typeof ypOfficialSuburb==='function'&&ypOfficialSuburb(id))||'',flow,status:'',limitation:'',action:null});}else{card.className='card';const h=document.createElement('h2');h.textContent='You Board Here';card.appendChild(h);}const shut=()=>panel.remove();if(typeof ypHeaderDismiss==='function')ypHeaderDismiss(card.querySelector('.hwh, .yp-card-head'),shut);ypMarketBtn(card,'hwx','Back',shut);if(typeof ypPinStepFooter==='function')ypPinStepFooter(card);panel.appendChild(card);document.body.appendChild(panel);}

function ypSaleListPrice(item){const id=item&&item.id;const ask=id&&ypMarketAsking(id);if(ask>0)return ask;return typeof ypListingSalePrice==='function'?ypListingSalePrice(id,item):0;}
function ypEndSaleOccupants(id,week,s){week=week||(typeof ypWeekNow==='function'?ypWeekNow():0);s=s||(typeof ypEnsureMarket==='function'?ypEnsureMarket():null);if(!s)return;const board=s.board&&s.board[id];(board&&board.boarders||[]).forEach(b=>{if(!b||b.endedWeek)return;b.endedWeek=week;if(typeof ypOwnEndHistory==='function')ypOwnEndHistory(id,'boarder',Math.round(+b.boardWk||+(board&&board.boardWk)||0));});const rent=s.rents&&s.rents[id];if(rent&&rent.tenant){const amt=Math.round(+rent.rent||0);rent.status='withdrawn';delete rent.tenant;rent.m2m=0;delete rent.lastChargedWeek;if(typeof ypOwnEndHistory==='function')ypOwnEndHistory(id,'tenant',amt);}try{if(typeof G!=='undefined'&&G){G.rooms=G.rooms||{};const raw=G.rooms[id];const share=(typeof ypOwnRoomSharePeople==='function'?ypOwnRoomSharePeople(id):[])||[];share.forEach((x,i)=>{if(typeof ypOwnEndHistory==='function')ypOwnEndHistory(id,'share',Math.round(+x.price||0));});if(raw&&Array.isArray(raw.list))raw.list.forEach(row=>{if(row)row.b=null;});else if(raw&&Array.isArray(raw.boarders))raw.boarders.length=0;}}catch(e){}}
function ypOwnListingStatus(b){if(!b||typeof ypIsOwnSaleListing!=='function'||!ypIsOwnSaleListing(b.id))return '';const L=typeof ypSaleListing==='function'?ypSaleListing(b.id):null;if(L&&L.status==='agreed')return 'Awaiting Settlement';if(L&&L.status==='accepted')return 'Sale Agreed';return 'Listed For Sale';}
